def sum_upper_triangle(matrix):
    total = 0
    n = len(matrix)
    for i in range(n):
        for j in range(i, n):
            total += matrix[i][j]
    return total

def redundant_max(items):
    result = []
    for i in range(len(items)):
        current_max = items[0]
        for j in range(len(items)):
            if items[j] > current_max:
                current_max = items[j]
        result.append(current_max)
    return result

